import AppKit

/// 메뉴바 아이콘 — 이름(icon1~5) × 스테이지(stage1~5)로 앱에 내장(투명 44px PNG).
/// 설정에서 아이콘(이름)을 고르고(=iconIndex), 상태(stage)는 AppState.iconStage 로
/// 바꾼다. 상태가 바뀌면 같은 아이콘의 다른 스테이지로 교체된다.
enum AppIcons {
    static let iconCount = 5   // 이름 수 (icon1..icon5)
    static let stageCount = 5  // 상태 수 (stage1..stage5)
    static let names = ["icon1", "icon2", "icon3", "icon4", "icon5"]

    /// 원본(44px) NSImage — 설정 썸네일용. stage 기본 0(=stage1).
    static func rawImage(icon: Int, stage: Int = 0) -> NSImage? {
        guard base64.indices.contains(icon),
              base64[icon].indices.contains(stage),
              let data = Data(base64Encoded: base64[icon][stage])
        else { return nil }
        return NSImage(data: data)
    }

    /// 메뉴바 글리프 포인트 크기 — 표준 18pt 의 1.5배. 메뉴바 두께(≈22~24pt)를
    /// 넘어 잘리면 이 상수만 낮추면 된다.
    static let menuBarPointSize: CGFloat = 27

    /// 메뉴바 표시용 — 템플릿 렌더링(단색, 메뉴바 대비색으로 또렷하게).
    /// 가는 선 컬러 아이콘이 작게 축소되면 흐려지므로, 메뉴바에선 알파를 마스크로
    /// 써서 선명한 글리프로 그린다. (설정 썸네일은 rawImage 로 컬러 유지)
    /// 원본의 얇은 선은 알파가 낮아 그대로 마스킹하면 반투명 회색으로 뿌옇게
    /// 보인다 — 알파를 증폭해 거의 불투명한 글리프로 만든다.
    static func menuBarImage(icon: Int, stage: Int = 0) -> NSImage? {
        guard let img = rawImage(icon: icon, stage: stage) else { return nil }
        let crisp = alphaBoosted(img, boost: 3.0) ?? img
        crisp.size = NSSize(width: menuBarPointSize, height: menuBarPointSize)
        crisp.isTemplate = true
        return crisp
    }

    /// 커스텀 아이콘 파일 → 메뉴바 크기 NSImage. 컬러 원본을 그대로 쓴다(비템플릿 —
    /// 임의 이미지는 배경이 불투명할 수 있어 템플릿 마스킹이 어울리지 않는다).
    /// 파일이 없거나 이미지가 아니면 nil — 호출부가 내장 아이콘으로 폴백한다.
    static func customMenuBarImage(path: String) -> NSImage? {
        guard !path.isEmpty, let img = NSImage(contentsOfFile: path), img.isValid else {
            return nil
        }
        let size = img.size
        guard size.width > 0, size.height > 0 else { return nil }
        let scale = menuBarPointSize / max(size.width, size.height)
        img.size = NSSize(width: size.width * scale, height: size.height * scale)
        img.isTemplate = false
        return img
    }

    /// 커스텀 아이콘 원본 로드 — 설정 썸네일용.
    static func customRawImage(path: String) -> NSImage? {
        guard !path.isEmpty else { return nil }
        return NSImage(contentsOfFile: path)
    }

    /// 픽셀 알파를 `boost` 배(상한 1.0)로 증폭한 사본 — 템플릿 마스크 농도 보정용.
    /// 완전 투명(0)은 그대로 배경으로 남고, 옅은 선(0.2~0.4)이 진해진다. 44px 원본
    /// 기준 픽셀 순회라 비용은 무시할 수준.
    private static func alphaBoosted(_ image: NSImage, boost: CGFloat) -> NSImage? {
        guard let tiff = image.tiffRepresentation,
              let src = NSBitmapImageRep(data: tiff)
        else { return nil }
        let width = src.pixelsWide
        let height = src.pixelsHigh
        guard width > 0, height > 0,
              let rep = NSBitmapImageRep(
                  bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height,
                  bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                  colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0
              )
        else { return nil }

        for y in 0..<height {
            for x in 0..<width {
                let alpha = src.colorAt(x: x, y: y)?.alphaComponent ?? 0
                // 템플릿은 알파만 보므로 RGB 는 아무 값이어도 된다(검정 고정).
                rep.setColor(
                    Palette.iconMaskNS(alpha: alpha * boost),
                    atX: x, y: y
                )
            }
        }

        let out = NSImage(size: image.size)
        out.addRepresentation(rep)
        return out
    }

    // base64[iconIndex][stageIndex]  (icon1..5 × stage1..5)
    private static let base64: [[String]] = [
        [
            "",
            "",
            "",
            "",
            "",
        ],
        [
            "",
            "",
            "",
            "",
            "",
        ],
        [
            "",
            "",
            "",
            "",
            "",
        ],
        [
            "",
            "",
            "",
            "",
            "",
        ],
        [
            "",
            "",
            "",
            "",
            "",
        ],
    ]
}
